output_text:
[
  {
    "id": "entry_cart_pickup_required",
    "text": "A shopper is obliged to take the entry cart before continuing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "entry_cart_bay": "at(1,5)",
        "entry_cart_available": {
          "and": [
            "entry_cart_bay",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "entry_cart_acquired": {
          "pre": {
            "and": [
              "entry_cart_available",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "entry_cart_acquired"
    }
  },
  {
    "id": "no_item_pickup_without_cart",
    "text": "A shopper is prohibited from picking up shelf items unless they currently have a cart.",
    "abstraction": {
      "state_properties": {
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "cartless",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "A shopper is prohibited from carrying grocery items by hand rather than placing them in a cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull",
        "hands_free": {
          "not": "handFull"
        }
      },
      "events": {
        "becomes_hand_full": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_item_by_hand",
          "becomes_hand_full"
        ]
      }
    }
  },
  {
    "id": "cart_parking_only_at_service_point",
    "text": "A shopper is prohibited from putting a cart down anywhere except the designated top-left service point.",
    "abstraction": {
      "state_properties": {
        "top_left_service_point": "at(0,1)",
        "not_service_point": {
          "not": "top_left_service_point"
        }
      },
      "events": {
        "cart_put_down": {
          "pre": {
            "and": [
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cart_put_down_at_service_point": {
          "pre": {
            "and": [
              "top_left_service_point",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "LEAVE_CART",
          "not_service_point"
        ]
      }
    }
  },
  {
    "id": "top_left_cart_check_required",
    "text": "A shopper is obliged to perform the top-left cart check by setting the cart down at the top-left service point before exiting.",
    "abstraction": {
      "state_properties": {
        "top_left_service_point": "at(0,1)",
        "with_cart_at_top_left": {
          "and": [
            "top_left_service_point",
            "hasCart"
          ]
        }
      },
      "events": {
        "top_left_cart_check_started": {
          "pre": {
            "and": [
              "with_cart_at_top_left",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "top_left_cart_check_started"
    }
  },
  {
    "id": "reclaim_service_cart",
    "text": "After setting a cart down at the top-left service point, the shopper is obliged to reclaim that cart before leaving it behind.",
    "abstraction": {
      "state_properties": {
        "top_left_service_point": "at(0,1)",
        "service_cart_waiting": {
          "and": [
            "top_left_service_point",
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "service_cart_deposited": {
          "pre": {
            "and": [
              "top_left_service_point",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        },
        "service_cart_reclaimed": {
          "pre": {
            "and": [
              "service_cart_waiting",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "service_cart_deposited",
      "discharge": "service_cart_reclaimed"
    }
  },
  {
    "id": "no_departing_from_parked_service_cart",
    "text": "A shopper is prohibited from moving away from the top-left service point while the cart is parked there and not in their possession.",
    "abstraction": {
      "state_properties": {
        "top_left_service_point": "at(0,1)",
        "unreclaimed_service_cart": {
          "and": [
            "top_left_service_point",
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "move_away_from_unreclaimed_service_cart": {
          "pre": {
            "and": [
              "unreclaimed_service_cart",
              "MOVE"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "move_away_from_unreclaimed_service_cart"
    }
  },
  {
    "id": "loaded_cart_must_exit_with_shopper",
    "text": "Once any item has been loaded while using a cart, the shopper is obliged to exit while still possessing the cart.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "at_exit_door": "at(9,5)"
      },
      "events": {
        "item_loaded_into_cart": {
          "pre": {
            "and": [
              "with_cart",
              "PICKUP_ITEM"
            ]
          },
          "post": "hasCart"
        },
        "exit_with_cart": {
          "pre": {
            "and": [
              "at_exit_door",
              "hasCart",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "item_loaded_into_cart",
      "discharge": "exit_with_cart"
    }
  }
]
